// ─── Configuración ────────────────────────────────────────────────────────
// YouTube usa dos APIs distintas, ambas de autoservicio:
//   · Data API v3        → canal, vídeos y miniaturas
//   · YouTube Analytics  → vistas, retención y suscriptores del periodo
//
// La credencial de YouTube de n8n NO trae por defecto el permiso de analíticas.
// Activa "Custom Scopes" en la credencial y añade:
//   https://www.googleapis.com/auth/youtube.readonly
//   https://www.googleapis.com/auth/yt-analytics.readonly
//
// El canal se resuelve solo con mine=true: no hay que configurar ningún id.
const AJUSTES = {
  DATA_HOST: 'https://www.googleapis.com',
  ANALYTICS_HOST: 'https://youtubeanalytics.googleapis.com',
};

const env = (() => { try { return $env ?? {}; } catch { return {}; } })();
const DATA_HOST = env.YT_DATA_HOST || AJUSTES.DATA_HOST;
const ANALYTICS_HOST = env.YT_ANALYTICS_HOST || AJUSTES.ANALYTICS_HOST;

const RANGE_DAYS = { '7d': 7, '30d': 30, '90d': 90, '12m': 365 };
const range = $input.first().json.query?.range ?? '30d';
const days = RANGE_DAYS[range] ?? 30;

// La Analytics API espera fechas AAAA-MM-DD, no marcas de tiempo.
const iso = (d) => d.toISOString().slice(0, 10);
const endDate = iso(new Date(Date.now() - 86400000));   // ayer: hoy aún no está consolidado
const startDate = iso(new Date(Date.now() - (days + 1) * 86400000));

return [{ json: { dataHost: DATA_HOST, analyticsHost: ANALYTICS_HOST, range, days, startDate, endDate } }];

// Une canal y analíticas en la forma que espera el panel.
const cfg = $('Configuración').first().json;
const ch = $('Canal').first().json ?? {};
const an = $('Analíticas').first().json ?? {};

const errors = [ch.error?.message, an.error?.message].filter(Boolean);
const channel = ch.items?.[0] ?? null;

// La Analytics API devuelve columnHeaders + rows: se indexa por nombre.
const cols = (an.columnHeaders ?? []).map((c) => c.name);
const row = an.rows?.[0] ?? [];
const metric = (name) => {
  const i = cols.indexOf(name);
  return i === -1 ? null : row[i];
};

const miles = (n) => String(n).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
const fmt = (n) => (n == null ? null
  : n >= 1e6 ? (n / 1e6).toFixed(2) + 'M'
  : n >= 1e3 ? (n / 1e3).toFixed(1) + 'K'
  : String(n));

const views = metric('views');
const retention = metric('averageViewPercentage');
const gained = metric('subscribersGained');
const minutes = metric('estimatedMinutesWatched');

const captions = { '7d': 'vs semana anterior', '30d': 'vs mes anterior',
                   '90d': 'vs trimestre anterior', '12m': 'vs año anterior' };

return [{ json: {
  source: 'youtube',
  range: cfg.range,
  errors,
  account: {
    name: channel?.snippet?.title ?? null,
    handle: channel?.snippet?.customUrl ?? null,
    audience: channel?.statistics?.subscriberCount
      ? miles(Number(channel.statistics.subscriberCount)) + ' suscriptores'
      : null,
    uploads: channel?.contentDetails?.relatedPlaylists?.uploads ?? null,
  },
  kpis: {
    vistas: { value: fmt(views), caption: captions[cfg.range] },
    // A diferencia de Instagram, YouTube sí da retención real.
    retencion: { value: retention == null ? null : retention.toFixed(1) + '%',
                 caption: 'del vídeo visto de media' },
    suscriptores: { value: gained == null ? null : '+' + miles(gained), caption: 'ganados en el periodo' },
    // El dato de ejemplo hablaba de clicks en la descripción, que la API no da;
    // se sustituye por el tiempo de visualización, que es la métrica de YouTube.
    clicks: { label: 'Tiempo de visualización',
              value: minutes == null ? null : fmt(Math.round(minutes / 60)) + ' h',
              caption: 'horas vistas en el periodo' },
  },
} }];
